INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t1-w1-engli', 1, 'English Studies', 1, 1, 'instructional', 'Instructional Week 1 · Foundational Phonics & Letter Sounds', 'Universal Basic Education Core Scheme', 'Pre-Reading Skills: Phonemic Awareness (Identifying Sounds)', 'Letter-Sound Identification (/a/, /b/, /c/, /d/) & Sound Production', '[]'::jsonb, '[{"title":"Letter Sound Flashcards","description":"Large colorful cards showing letters A, B, C with an apple, a ball, and a cup.","itemType":"shapes_chart","icon":"🔤","caption":"Phonics Sound Cards"},{"title":"Classroom Sound Box","description":"A box of small toys: a bell, a ball, an orange, and a toy car to test sound identification.","itemType":"general","icon":"📦","caption":"Sound Discovery Box"}]'::jsonb, '[{"id":"p1-eng-q1","question":"Which of these fruits starts with the /a/ sound?","contextNigerian":"Look at the fruits in the market tray.","options":["Banana","Apple","Mango","Orange"],"correctAnswerIndex":1,"explanation":"Apple begins with the /a/ sound: /æ/ - pple!","hint":"It is a red or green round fruit that starts with A."},{"id":"p1-eng-q2","question":"Amina sees a Cup on the table. What sound does the word \"Cup\" begin with?","contextNigerian":"Listen to the first sound: /k/ - up.","options":["/k/","/b/","/d/","/m/"],"correctAnswerIndex":0,"explanation":"\"Cup\" begins with the /k/ sound made by the letter C.","hint":"Make the sound at the back of your throat."},{"id":"p1-eng-q3","question":"Which word has the beginning sound /b/?","contextNigerian":"What do children kick on the school field during break time?","options":["Chair","Desk","Ball","Pencil"],"correctAnswerIndex":2,"explanation":"\"Ball\" begins with the letter B and the sound /b/.","hint":"It is round and bounces on the playground."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. What is a Letter Sound?","teacherSpeech":"Sannu kowa! In Primary 1, we learn that letters have names and letters make special sounds. When we say the letter \"A\", its sound is /æ/ like in \"Amina\" or \"Apple\"!","boardText":"LETTER SOUNDS (PHONEMIC AWARENESS)\n\n• Letter A says /æ/ → as in Apple 🍎, Ant 🐜\n• Letter B says /b/ → as in Ball ⚽, Book 📖\n• Letter C says /k/ → as in Cup ☕, Cat 🐱","bulletPoints":["Every letter makes a sound with our mouth","We use our listening ears to hear the beginning sound","We say the sound clearly together!"],"equationOrHighlight":"A = /æ/ | B = /b/ | C = /k/","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Clapping Out the Sounds","teacherSpeech":"Let us clap whenever we hear the /b/ sound. Listen: \"Ball!\" (Clap!). \"Banana!\" (Clap!). \"Book!\" (Clap!). Excellent listening, champions!","boardText":"LISTENING & BLENDING\n\n• /b/ + /æ/ + /t/ = BAT 🏏\n• /k/ + /æ/ + /t/ = CAT 🐱\n• /æ/ + /t/ = AT","bulletPoints":["Listen to each individual sound","Put the sounds together smoothly to make a word"],"equationOrHighlight":"/k/ + /æ/ + /t/ = CAT","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
