INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t1-w1-mathe', 1, 'Mathematics', 1, 1, 'instructional', 'Instructional Week 1 · Counting Objects 1 to 5 & Number Recognition', 'Universal Basic Education Core Scheme', 'Whole Numbers 1–5', 'Counting, Identification, and Writing Numbers 1 to 5', '[]'::jsonb, '[{"title":"Counting Oranges","description":"Five fresh, ripe Nigerian oranges lined up on a wooden table.","itemType":"oranges","icon":"🍊","caption":"Counting 1, 2, 3, 4, 5 Oranges"},{"title":"Counting Fingers Hand Chart","description":"A colorful chart showing 1 finger, 2 fingers, up to 5 fingers on one hand.","itemType":"shapes_chart","icon":"🖐️","caption":"One Hand = 5 Fingers"}]'::jsonb, '[{"id":"p1-mat-q1","question":"Chinedu has 4 ripe bananas in his bag. Which numeral shows 4?","contextNigerian":"Look closely at the numbers.","options":["2","3","4","5"],"correctAnswerIndex":2,"explanation":"The numeral 4 represents four items.","hint":"It is the number right after 3."},{"id":"p1-mat-q2","question":"Which group has exactly 2 objects?","contextNigerian":"Count the items in each choice.","options":["⚽","⚽⚽","⚽⚽⚽","⚽⚽⚽⚽"],"correctAnswerIndex":1,"explanation":"⚽⚽ has two balls.","hint":"Look for a pair of footballs."},{"id":"p1-mat-q3","question":"What number comes immediately after 4 when counting forward?","contextNigerian":"1, 2, 3, 4, ___?","options":["2","3","5","6"],"correctAnswerIndex":2,"explanation":"Counting forward: 1, 2, 3, 4, 5. The number after 4 is 5.","hint":"Count the fingers on one hand."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. Counting Objects 1 to 5","teacherSpeech":"Look at the oranges on our table. Let us count them together one by one: 1 orange, 2 oranges, 3 oranges, 4 oranges, 5 oranges! On one hand, we have exactly five fingers!","boardText":"COUNTING WHOLE NUMBERS 1 TO 5\n\n1 🍊 (One orange)\n2 🍊🍊 (Two oranges)\n3 🍊🍊🍊 (Three oranges)\n4 🍊🍊🍊🍊 (Four oranges)\n5 🍊🍊🍊🍊🍊 (Five oranges)","bulletPoints":["Point to each object as you count","Say the number loud and proud","The last number you say is the total amount"],"equationOrHighlight":"1 • 2 • 3 • 4 • 5","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Writing the Numerals","teacherSpeech":"Number 1 is like a straight standing stick: down we go and that is one! Number 2 is around and back on the railway track: two, two, two!","boardText":"HOW TO WRITE 1 TO 5\n\n1 : One straight line down\n2 : Curve around and flat across the bottom\n3 : Around a tree, around a tree\n4 : Down and over, down once more\n5 : Short neck, belly fat, number 5 wears a hat!","bulletPoints":["Practice tracing with your finger in the air","Count the dots to check your answer"],"equationOrHighlight":"1, 2, 3, 4, 5","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
