INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t1-w1-physi', 1, 'Physical and Health Education', 1, 1, 'instructional', 'Instructional Week 1 · Healthy Bodies & Joyful Movement', 'Universal Basic Education Core Scheme', 'Motor Skills Development: Moving Our Body Parts 1', 'Identifying and moving body parts: head, shoulders, arms, hands, legs, and feet', '[]'::jsonb, '[{"title":"Full Body Movement Chart","description":"Large illustration of an active Nigerian school pupil demonstrating head, shoulder, arm, waist, leg, and foot movements.","itemType":"shapes_chart","icon":"🏃🏾","caption":"Our Active Body Parts"},{"title":"Action Posture Cards","description":"Four cards showing: 1. Standing tall, 2. Raising arms to the sky, 3. Marching in place, 4. Touching toes.","itemType":"shapes_chart","icon":"🧍🏾","caption":"Stretch and Balance Postures"}]'::jsonb, '[{"id":"p1-phe-q1","question":"Which of the following body parts is located on your upper body between your neck and your arms?","contextNigerian":"Place your hands right here on your body.","options":["Knees","Shoulders","Toes","Ankles"],"correctAnswerIndex":1,"explanation":"Our shoulders connect our neck to our arms on our upper body.","hint":"In the song: \"Head, shoulders, knees and toes!\""},{"id":"p1-phe-q2","question":"Why is it important to do simple stretching exercises every morning before learning?","contextNigerian":"Think about how you feel after morning assembly.","options":["To make us feel sleepy and tired","To keep our bodies active, flexible, and healthy","To spoil our school uniform","So we cannot write with our pencils"],"correctAnswerIndex":1,"explanation":"Stretching and exercising keeps our muscles flexible and our minds awake and alert.","hint":"It gives us energy and keeps our bodies strong."},{"id":"p1-phe-q3","question":"How many toes do we have on our two feet combined?","contextNigerian":"Count 5 toes on your left foot and 5 toes on your right foot.","options":["5 toes","8 toes","10 toes","12 toes"],"correctAnswerIndex":2,"explanation":"We have 5 toes on each foot, making a total of 10 toes.","hint":"Just like we have 10 fingers on our two hands."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. Naming Our Body Parts","teacherSpeech":"Good day active champions! Stand up straight and let us play \"Teacher Says\"! Teacher says: touch your head! Good! Teacher says: touch your two shoulders! Wonderful! Now wiggle your ten fingers in the air like stars! Our bodies have three main sections: head at the top, trunk in the middle, and limbs (arms and legs) that help us move.","boardText":"OUR BODY PARTS\n\n• Top: Head, neck, eyes, ears 🗣️\n• Middle: Shoulders, chest, waist 👕\n• Limbs:\n  - Arms, elbows, hands, fingers (Upper Limbs) ✋\n  - Thighs, knees, legs, feet, toes (Lower Limbs) 🦵","bulletPoints":["Every body part has a special job","Hands help us write, eat, and clap","Legs and feet help us walk, march, and jump"],"equationOrHighlight":"Head • Shoulders • Knees • Toes","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Safe and Healthy Body Movements","teacherSpeech":"Let us practice moving each part without bumping into our neighbors. Gently nod your head up and down: \"Yes, yes, yes\". Slowly turn your head left and right: \"No, no, no\". Shrug your shoulders up to your ears and let them drop! Now march on the spot: one-two, one-two! Moving every day keeps our blood flowing and our minds sharp.","boardText":"SAFE WARM-UP MOVEMENTS\n\n1. Head Nodding: Up and down gently\n2. Shoulder Rolls: Backward and forward\n3. Arm Reaches: Stretch high to touch the clouds!\n4. Knee Bends: Gentle bend and stand tall\n5. Spot Marching: Lift knees high, 1-2, 1-2!","bulletPoints":["Keep your space: do not bump into classmates","Breathe in fresh air through your nose, out through your mouth","Drink clean water after exercising"],"equationOrHighlight":"Exercise = Strong Heart + Happy Mind","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
