INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t1-w1-islam', 1, 'Islamic Studies', 1, 1, 'instructional', 'Instructional Week 1 · First Steps in the Arabic Alphabet (أ to خ)', 'Universal Basic Education Core Scheme', 'Arabic Alphabet (Part 1)', 'Introduction to the first seven Arabic letters: Alif, Baa, Taa, Thaa, Jeem, Haa, Khaa (أ ب ت ث ج ح خ)', '[]'::jsonb, '[{"title":"First 7 Arabic Letters Slate (Alif to Khaa)","description":"Large wooden writing slate showing أ, ب, ت, ث, ج, ح, خ in clear calligraphy with bright red dot markers.","itemType":"shapes_chart","icon":"📜","caption":"Arabic Letters: أ ب ت ث ج ح خ"},{"title":"The Boat Letters Family Chart","description":"Illustration comparing Baa (one dot under), Taa (two dots inside), and Thaa (three dots inside) like small canoes.","itemType":"shapes_chart","icon":"🛶","caption":"The Boat Family: Baa, Taa, Thaa"}]'::jsonb, '[{"id":"p1-is-q1","question":"What is the very first letter of the Arabic alphabet?","contextNigerian":"It stands straight and tall with no dots.","options":["Baa (ب)","Taa (ت)","Alif (أ)","Jeem (ج)"],"correctAnswerIndex":2,"explanation":"Alif (أ) is the first letter of the Arabic alphabet.","hint":"It looks like a straight standing vertical line."},{"id":"p1-is-q2","question":"How many dots does the letter Taa (ت) have on top?","contextNigerian":"Look at the two eyes sitting inside the boat: ت.","options":["No dots","One dot","Two dots","Four dots"],"correctAnswerIndex":2,"explanation":"Taa (ت) has exactly two dots placed above the boat line.","hint":"Count the dots: one, two!"},{"id":"p1-is-q3","question":"Among the curved letters ج, ح, and خ, which one has NO dots at all?","contextNigerian":"Look at the clean, smooth letter: ح.","options":["Jeem (ج)","Haa (ح)","Khaa (خ)","Thaa (ث)"],"correctAnswerIndex":1,"explanation":"Haa (ح) is written completely clean without any dots.","hint":"Jeem has a dot in its tummy and Khaa has a dot on its head."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. Reading Right to Left & Letter Alif (أ)","teacherSpeech":"Assalamu Alaikum, my lovely scholars! In Arabic, we read from right to left! Look at our first letter: ALIF (أ). It stands tall and straight like a walking stick or a tall pencil. When we say Alif, we open our mouth gently. Say it with me: \"ALIF!\"","boardText":"THE ARABIC ALPHABET (READ RIGHT TO LEFT ➡️ ⬅️)\n\n1. أ (Alif) → Straight line from top to bottom\n• Sound: Clear open sound like /a/\n• Looks like: A standing staff or pencil ✏️","bulletPoints":["Arabic is read from RIGHT to LEFT","Alif is the very first letter","Alif has no dots"],"equationOrHighlight":"Letter 1: أ (Alif)","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. The Boat Family and The Curved Family","teacherSpeech":"Now meet the Boat Family: Baa (ب), Taa (ت), and Thaa (ث). They all have the same boat shape, but notice the dots! Baa has ONE dot underneath (like a fish swimming under the boat). Taa has TWO dots inside at the top (like two friendly eyes). Thaa has THREE dots at the top! Next come the curved letters: Jeem (ج) has a dot in its tummy, Haa (ح) has no dot, and Khaa (خ) has a dot sitting on its head!","boardText":"DOTS MAKE THE DIFFERENCE!\n\n• THE BOAT FAMILY:\n  - ب (Baa) → 1 dot BELOW\n  - ت (Taa) → 2 dots ABOVE\n  - ث (Thaa) → 3 dots ABOVE\n\n• THE CURVED FAMILY:\n  - ج (Jeem) → 1 dot in the tummy\n  - ح (Haa) → Clean! No dot at all\n  - خ (Khaa) → 1 dot on top of the head","bulletPoints":["Count the dots to know the letter","ب has one dot under the line","ت has two dots on top","ج, ح, خ share the same curved tail"],"equationOrHighlight":"أ • ب • ت • ث • ج • ح • خ","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
