INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w1-socia', 1, 'Social and Citizenship Studies', 3, 1, 'instructional', 'Week 1 · Third Term', NULL, 'Attitudes and Values', 'Understanding attitudes (how we think and feel about things)  Understanding values (what we believe is important)  Good attitudes: positive thinking, cheerfulness, willingness to help  Bad attitudes: complaining, laziness, selfishness  Nigerian core values: honesty, hard work, respect, integrity, patriotism', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 1 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w2-socia', 1, 'Social and Citizenship Studies', 3, 2, 'instructional', 'Week 2 · Third Term', NULL, 'Finding Help in Danger (Part 1)', 'Understanding danger (situations that can harm us)  Types of danger: fire, accidents, getting lost, strangers, bad weather  Emergency situations: accidents, illness, natural disasters  People who can help: parents, teachers, police, doctors, firefighters  Importance of staying calm in dangerous situations', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 2 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w3-socia', 1, 'Social and Citizenship Studies', 3, 3, 'instructional', 'Week 3 · Third Term', NULL, 'Finding Help in Danger (Part 2)', 'Emergency numbers in Nigeria: 112 (emergency), 767 (police in Lagos), 199 (fire service)  What information to give: name, location, type of emergency  Trusted adults to run to for help  Safety rules: don''t talk to strangers, don''t follow strangers, don''t accept gifts from strangers  Knowing your parents'' phone numbers and home address  "Stranger Danger" awareness', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 3 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w4-socia', 1, 'Social and Citizenship Studies', 3, 4, 'instructional', 'Week 4 · Third Term', NULL, 'Secure Environment (Part 1)', 'Understanding a secure environment (a place where we are safe)  What makes a place secure: locks on doors, fences, lights, security guards  Feeling safe at home, school, and community  Dangers in our environment: open wells, busy roads, sharp objects, fire  How to stay safe: following rules, staying alert, reporting dangers', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 4 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
