INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w7-socia', 1, 'Social and Citizenship Studies', 3, 7, 'instructional', 'Week 7 · Third Term', NULL, 'Secure Environment (Part 2) & Climate Change and the Environment', 'Keeping our environment clean and safe: proper waste disposal, not littering  Reporting broken or dangerous things to adults  Understanding weather and climate (sun, rain, wind, hot, cold)  Climate change (simple introduction): changes in weather patterns  Effects of climate change: too much heat, floods, droughts  Our role: planting trees, not wasting water, keeping environment clean', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 7 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w8-socia', 1, 'Social and Citizenship Studies', 3, 8, 'instructional', 'Week 8 · Third Term', NULL, 'Local Wildlife and Conservation', 'Understanding wildlife (animals living in nature)  Nigerian animals: monkeys, antelopes, birds, lizards, snakes, butterflies  Where animals live: forests, rivers, grasslands  Why we should protect animals: they are part of nature, some are endangered  Conservation means protecting nature  Not harming animals, not destroying their homes  Visiting zoos to learn about animals', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 8 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w9-socia', 1, 'Social and Citizenship Studies', 3, 9, 'instructional', 'Week 9 · Third Term', NULL, 'Money (Part 1)', 'Understanding money (what we use to buy things)  Nigerian currency: Naira (₦)  Coins: ₦1, ₦2 (if still in circulation)  Notes: ₦5, ₦10, ₦20, ₦50, ₦100, ₦200, ₦500, ₦1000  Identifying different denominations  Money has value - we work to earn money', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 9 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w10-socia', 1, 'Social and Citizenship Studies', 3, 10, 'instructional', 'Week 10 · Third Term', NULL, 'Money (Part 2)', 'Uses of money: buying food, clothes, toys, paying for school, transportation  Earning money: parents work to earn money  Spending wisely: buying what we need, not wasting money  Saving money: keeping money for future use (piggy bank, savings box)  Not stealing money - honesty with money  Simple buying and selling activities (role-play)  Appreciating what parents buy with money', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 10 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w11-socia', 1, 'Social and Citizenship Studies', 3, 11, 'revision', 'Week 11 · Third Term', NULL, 'REVISION', 'Review of all topics: Values, safety, environment, wildlife, money', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 11 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w12-socia', 1, 'Social and Citizenship Studies', 3, 12, 'examination', 'Week 12 · Third Term', NULL, 'EXAMINATION', 'End of Term Assessment', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 12 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w13-socia', 1, 'Social and Citizenship Studies', 3, 13, 'closing', 'Week 13 · Third Term', NULL, 'CLOSING/VACATION', 'Term ends', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Social and Citizenship Studies, Term 3, Week 13 (Page 656)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t1-w1-cultu', 1, 'Cultural and Creative Arts', 1, 1, 'instructional', 'Instructional Week 1 · The Joy of Colors & Shapes: What is Art?', 'Universal Basic Education Core Scheme', 'Art: Introduction to Art', 'Understanding what art is (creating beautiful things), forms of art (drawing, coloring, crafts), and art materials', '[]'::jsonb, '[{"title":"Classroom Art Materials Display Tray","description":"Neatly organized wooden tray holding a box of 12 wax crayons, drawing pencils, white paper sheets, and an eraser.","itemType":"shapes_chart","icon":"🎨","caption":"Our Art Tools"},{"title":"Colorful Pattern Picture Card","description":"Vibrant Nigerian pattern showing yellow sunshine, red hibiscus flowers, and green leaves drawn with crayons.","itemType":"shapes_chart","icon":"🖍️","caption":"Drawing with Primary Colors"}]'::jsonb, '[{"id":"p1-cca-q1","question":"What is art?","contextNigerian":"Think about making something lovely with your hands.","options":["Breaking classroom windows with stones","Creating beautiful things with our imagination and hands","Sleeping during afternoon lessons","Refusing to eat lunch"],"correctAnswerIndex":1,"explanation":"Art is the joyful creation of beautiful things using our minds and hands.","hint":"It brings beauty and happiness to our eyes."},{"id":"p1-cca-q2","question":"Which of the following is a tool used for drawing the initial outline of a picture?","contextNigerian":"You use this to draw lines before coloring them in.","options":["A pencil","A water cup","A lunchbox","A wristwatch"],"correctAnswerIndex":0,"explanation":"A pencil is used by artists to draw outlines, shapes, and figures.","hint":"It has graphite inside and makes a grey line on paper."},{"id":"p1-cca-q3","question":"After finishing your drawing, what is the right thing to do with your crayons and pencils?","contextNigerian":"Think of keeping your desk neat and tidy.","options":["Throw them on the classroom floor","Pack them neatly back into your pencil pouch or box","Break them in half and give them away","Leave them under your desk"],"correctAnswerIndex":1,"explanation":"Caring for art tools means packing them neatly into their box so they remain clean and ready for next time.","hint":"Put them away safely so they do not get stepped on or lost."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. What is Art?","teacherSpeech":"Hello creative artists! Look at your clothes, look at the colorful illustrations in your reading book, look at the bright flags in the school yard. All of that was designed through ART! Art is the wonderful way we use our imagination, our hearts, and our hands to create beautiful things that bring joy to others.","boardText":"WHAT IS ART?\n\n• Art = Creating beautiful things with our imagination and hands! 🎨\n• Forms of Art in Primary 1:\n  - ✏️ Drawing: Making lines and shapes with pencils\n  - 🖍️ Coloring: Filling shapes with bright crayons\n  - 🖌️ Painting: Spreading colors with a soft brush\n  - ✂️ Paper Craft: Folding and pasting clean paper shapes","bulletPoints":["Art helps us express our thoughts and feelings","Everyone can create art in their own unique way","Art makes our classrooms and homes beautiful"],"equationOrHighlight":"Imagination + Hands = Beautiful Art!","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Art Tools and Caring for Our Materials","teacherSpeech":"To make art, artists need tools! In our classroom, our most important tools are clean white paper, a sharp HB pencil, and colorful wax crayons. When using your crayons, hold them gently near the tip so they do not snap. And remember our golden rule: we color only on our paper sketchpads, NEVER on classroom walls or desks!","boardText":"OUR ART TOOLS & CARE RULES\n\n• Common Art Materials:\n  1. Plain drawing paper or sketchpad 📄\n  2. Lead pencil & soft eraser ✏️\n  3. Wax crayons & colored pencils 🖍️\n\n• GOLDEN RULES OF THE ART CLASS:\n  ✅ Color inside your drawing book\n  ✅ Put crayons back in their box after use\n  ❌ Do not write or draw on walls or desks","bulletPoints":["Take care of your art materials so they last all term","Share colors politely with your desk partner","Always wash your hands after art class"],"equationOrHighlight":"Color on Paper · Care for Your Tools","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
