INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p1-t3-w1-cultu', 1, 'Cultural and Creative Arts', 3, 1, 'instructional', 'Week 1 · Third Term', NULL, 'Performing Arts: Introduction', 'Understanding performing arts (acting, dancing, singing, storytelling)  Types of performing arts we''ll learn: rhymes, folktales, songs  Importance of performing arts: entertainment, education, cultural preservation  Expressing ourselves through performance  Overcoming shyness: it''s okay to perform!', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 1 Cultural and Creative Arts, Term 3, Week 1 (Page 663)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
