INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p2-t1-w1-mathe', 2, 'Mathematics', 1, 1, 'instructional', 'Instructional Week 1 · Whole Numbers 1 to 100 & Place Value Bundles', 'Universal Basic Education Core Scheme', 'Whole Numbers (1–100)', 'Counting 1 to 100, Place Value (Tens and Units), Reading and Writing in Words', '[]'::jsonb, '[{"title":"Bundles of 10 Counting Sticks","description":"Ten bundles of broomsticks, each tied with a rubber band to represent 1 Ten.","itemType":"cowries","icon":"🥢","caption":"1 Bundle = 1 Ten (10 Units)"},{"title":"100-Square Number Grid","description":"A 10x10 colorful chart showing numbers 1 through 100.","itemType":"shapes_chart","icon":"🔢","caption":"100-Square Number Board"}]'::jsonb, '[{"id":"p2-w1-q1","question":"What is the value of 6 Tens and 3 Units?","contextNigerian":"Combine 6 bundles of ten sticks and 3 single sticks.","options":["36","63","603","9"],"correctAnswerIndex":1,"explanation":"6 Tens (60) + 3 Units (3) = 63.","hint":"Put the 6 in the Tens column and 3 in the Units column."},{"id":"p2-w1-q2","question":"Which of the following numbers is the greatest?","contextNigerian":"Compare the tens digits first.","options":["68","86","79","81"],"correctAnswerIndex":1,"explanation":"86 has 8 tens and 6 units, which is greater than 81, 79, and 68.","hint":"Both 86 and 81 have 8 tens. Which has more units?"},{"id":"p2-w1-q3","question":"What number comes immediately after 99 when counting forward?","contextNigerian":"Think about when you add 1 more to 99.","options":["98","100","101","110"],"correctAnswerIndex":1,"explanation":"99 + 1 = 100 (One Hundred).","hint":"It is a 3-digit number with two zeros."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. Grouping in Tens and Units","teacherSpeech":"Welcome to Primary 2! Today we count up to 100. Look at these sticks. Instead of counting single sticks all day, we tie 10 sticks together into a bundle. One bundle is called 1 TEN. If we have 3 bundles and 4 loose sticks, we have 3 Tens and 4 Units = 34!","boardText":"PLACE VALUE: TENS (T) & UNITS (U)\n\n• Number 34:\n  3 Tens = 30\n  4 Units = 4\n  30 + 4 = 34 (Thirty-four)\n\n• Number 50:\n  5 Tens = 50\n  0 Units = 0","bulletPoints":["Units = Single loose objects (0 to 9)","Tens = Bundles of 10 objects","10 Tens together make ONE HUNDRED (100)"],"equationOrHighlight":"Tens (T) | Units (U) -> 3 Tens + 4 Units = 34","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Writing Numbers in Words","teacherSpeech":"Let us practice writing numbers in words. 10 is ten, 20 is twenty, 30 is thirty, 40 is forty, and 100 is one hundred!","boardText":"NUMBERS IN WORDS\n\n• 14 = Fourteen\n• 40 = Forty (Notice: F-O-R-T-Y)\n• 75 = Seventy-five\n• 100 = One hundred","bulletPoints":["Read the Tens first, then the Units","Always put a hyphen between tens and units: twenty-five, sixty-three"],"equationOrHighlight":"40 = Forty | 100 = One Hundred","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
