INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p3-t1-w1-basic', 3, 'Basic Science & Technology', 1, 1, 'instructional', 'Instructional Week 1 · Understanding Length & Measurement Methods', 'Universal Basic Education Core Scheme', 'Measurement of Length I', 'Meaning of Length, Traditional Units (Handspan, Arm length, Footsteps) and Metric Units', '[]'::jsonb, '[{"title":"Traditional Handspan vs Ruler","description":"Illustration showing an outstretched palm (handspan) next to a 30cm plastic school ruler.","itemType":"shapes_chart","icon":"🖐️","caption":"Handspan vs. 30cm Metric Ruler"},{"title":"Measuring Tape & Metre Rule","description":"A wooden 1-metre ruler used by teachers and a flexible tailor measuring tape.","itemType":"measuring_cylinder","icon":"📏","caption":"Standard Measuring Tools"}]'::jsonb, '[{"id":"p3-sci-q1","question":"Why do scientists and builders use standard rulers instead of footsteps to measure a room?","contextNigerian":"Consider what happens when a tall person and a small pupil pace the same room.","options":["Because footsteps are too fast","Because everyone’s footstep size is different, so it gives inaccurate results","Because rulers are cheaper than shoes","Because footsteps can only measure water"],"correctAnswerIndex":1,"explanation":"Different people have different foot and hand sizes, making non-standard measurements inconsistent.","hint":"Think about whether your shoe is the same size as your parent’s shoe."},{"id":"p3-sci-q2","question":"Which instrument would a tailor use to measure your waist for a new school uniform?","contextNigerian":"Think about the flexible tool the tailor wraps around you.","options":["Thermometer","Measuring tape","Weighing scale","Stopwatch"],"correctAnswerIndex":1,"explanation":"A tailor uses a flexible measuring tape to measure body curves and lengths.","hint":"It can bend easily around a person’s body."},{"id":"p3-sci-q3","question":"What is the best standard unit to measure the length of an exercise book?","contextNigerian":"Is a notebook huge like a football field or small?","options":["Kilometers (km)","Centimeters (cm)","Litres (L)","Kilograms (kg)"],"correctAnswerIndex":1,"explanation":"Small objects like exercise books and pens are measured in centimeters (cm).","hint":"Look at the numbers on a student desk ruler."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. What is Length?","teacherSpeech":"Good day champions! Today in Basic Science, we study length. Length is how long something is from one end to another end. If you measure the distance from your classroom door to the blackboard, that distance is length!","boardText":"MEANING OF LENGTH\n\n• Length is the distance between two fixed points or edges.\n• Examples:\n  - Length of your pencil\n  - Length of your classroom desk\n  - Height of your school flagpole","bulletPoints":["Length measures distance: long, short, wide, tall","Everything around us has a measurable length"],"equationOrHighlight":"Length = Distance from Point A to Point B","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Traditional vs Standard Units","teacherSpeech":"Long ago before rulers were made, our grandfathers measured using their bodies: handspans, footsteps, and arm lengths! But why is a handspan not accurate? Because a child has a small hand and an adult teacher has a big hand! That is why we now use standard units: centimeters (cm) and meters (m).","boardText":"MEASURING UNITS\n\n1. Traditional (Non-standard):\n   • Handspan (from tip of thumb to little finger)\n   • Footstep (paces along the floor)\n   • Arm length (cubit)\n   ⚠️ Problem: Everyone’s body is different!\n\n2. Standard (Metric):\n   • Centimetre (cm) for small objects (pencils, books)\n   • Metre (m) for larger distances (doors, rooms)\n   • 100 cm = 1 Metre","bulletPoints":["Standard units give the same measurement anywhere in the world","A 30cm ruler in Lagos is the exact same length as a 30cm ruler in Kano!"],"equationOrHighlight":"100 cm = 1 Metre (m)","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
