INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w1-basic-part2', 4, 'Basic Digital Literacy', 1, 1, 'instructional', 'Week 1 · First Term', NULL, 'Introduction to Digital Devices Understanding technology and digital devices. Types: computers, tablets, smartphones, smartwatches, cameras. Computer types: desktop, laptop, tablet. Basic parts: monitor, keyboard, mouse, CPU. Uses in daily life. Care and handling of devices. Computer lab safety rules.', 'Introduction to Digital Devices Understanding technology and digital devices. Types: computers, tablets, smartphones, smartwatches, cameras. Computer types: desktop, laptop, tablet. Basic parts: monitor, keyboard, mouse, CPU. Uses in daily life. Care and handling of devices. Computer lab safety rules.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 1 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w2-basic-part2', 4, 'Basic Digital Literacy', 1, 2, 'instructional', 'Week 2 · First Term', NULL, 'History of Digital Devices Evolution from abacus to modern computers. Five generations: vacuum tubes, transistors, integrated circuits, microprocessors, AI. Key inventors: Charles Babbage, Ada Lovelace. Changes in size, speed, and cost over time.', 'History of Digital Devices Evolution from abacus to modern computers. Five generations: vacuum tubes, transistors, integrated circuits, microprocessors, AI. Key inventors: Charles Babbage, Ada Lovelace. Changes in size, speed, and cost over time.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 2 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w3-basic-part2', 4, 'Basic Digital Literacy', 1, 3, 'instructional', 'Week 3 · First Term', NULL, 'Parts of Digital Devices I Hardware vs Software basics. Input devices: keyboard, mouse, microphone, scanner, webcam. Output devices: monitor, printer, speakers, headphones. Functions of each device. Proper use and care.', 'Parts of Digital Devices I Hardware vs Software basics. Input devices: keyboard, mouse, microphone, scanner, webcam. Output devices: monitor, printer, speakers, headphones. Functions of each device. Proper use and care.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 3 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w4-basic-part2', 4, 'Basic Digital Literacy', 1, 4, 'instructional', 'Week 4 · First Term', NULL, 'Parts of Digital Devices II Internal parts: CPU (brain), RAM (temporary memory), Hard Drive/Storage (permanent memory), Motherboard (connects everything). Power supply and cooling systems. How parts work together.', 'Parts of Digital Devices II Internal parts: CPU (brain), RAM (temporary memory), Hard Drive/Storage (permanent memory), Motherboard (connects everything). Power supply and cooling systems. How parts work together.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 4 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
