INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w8-basic-part2', 4, 'Basic Digital Literacy', 1, 8, 'instructional', 'Week 8 · First Term', NULL, 'Input Devices Detailed study of input devices. Keyboard: QWERTY layout, typing practice, special keys. Mouse: left/right click, scroll, drag and drop. Touchpad and touchscreen. Microphone for voice input. Scanner for documents and images.', 'Input Devices Detailed study of input devices. Keyboard: QWERTY layout, typing practice, special keys. Mouse: left/right click, scroll, drag and drop. Touchpad and touchscreen. Microphone for voice input. Scanner for documents and images.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 8 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w9-basic-part2', 4, 'Basic Digital Literacy', 1, 9, 'instructional', 'Week 9 · First Term', NULL, 'Output Devices Detailed study of output devices. Monitor: displaying information, screen resolution. Printer: types (inkjet, laser), printing documents. Speakers and headphones: audio output. Projector for presentations.', 'Output Devices Detailed study of output devices. Monitor: displaying information, screen resolution. Printer: types (inkjet, laser), printing documents. Speakers and headphones: audio output. Projector for presentations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 9 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t1-w10-basic-part2', 4, 'Basic Digital Literacy', 1, 10, 'instructional', 'Week 10 · First Term', NULL, 'Computer Care and Safety Proper handling: don''t drop, keep away from water and food. Cleaning: dust removal, screen cleaning, keyboard cleaning. Virus protection basics. Power management: proper shutdown, using surge protectors. Ergonomics: proper sitting position, screen height, keyboard position. Lab safety rules review.', 'Computer Care and Safety Proper handling: don''t drop, keep away from water and food. Cleaning: dust removal, screen cleaning, keyboard cleaning. Virus protection basics. Power management: proper shutdown, using surge protectors. Ergonomics: proper sitting position, screen height, keyboard position. Lab safety rules review.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 1, Week 10 (Page 826)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
