INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w1-basic-part2', 4, 'Basic Digital Literacy', 2, 1, 'instructional', 'Week 1 · Second Term', NULL, 'Interface Customization Understanding computer interface. Desktop: icons, wallpaper, taskbar. Customizing wallpaper and background. Organizing desktop icons. Changing mouse pointer and cursor. Sound settings adjustment. Screen brightness control.', 'Interface Customization Understanding computer interface. Desktop: icons, wallpaper, taskbar. Customizing wallpaper and background. Organizing desktop icons. Changing mouse pointer and cursor. Sound settings adjustment. Screen brightness control.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 1 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w2-basic-part2', 4, 'Basic Digital Literacy', 2, 2, 'instructional', 'Week 2 · Second Term', NULL, 'File Management I Understanding files and folders. File types: documents, pictures, videos, music. Creating new folders. Naming and renaming files. Moving and copying files. Deleting files and Recycle Bin.', 'File Management I Understanding files and folders. File types: documents, pictures, videos, music. Creating new folders. Naming and renaming files. Moving and copying files. Deleting files and Recycle Bin.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 2 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w3-basic-part2', 4, 'Basic Digital Literacy', 2, 3, 'instructional', 'Week 3 · Second Term', NULL, 'File Management II Organizing files in folders. Creating folder structure. Searching for files. File properties: size, date, type. Sorting files: by name, date, size. Backup basics: saving important files. USB flash drive usage.', 'File Management II Organizing files in folders. Creating folder structure. Searching for files. File properties: size, date, type. Sorting files: by name, date, size. Backup basics: saving important files. USB flash drive usage.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 3 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
