INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w7-basic-part2', 4, 'Basic Digital Literacy', 2, 7, 'instructional', 'Week 7 · Second Term', NULL, 'Digital Content Creation II Introduction to word processing. Opening Microsoft Word or similar program. Basic formatting: bold, italic, underline, font size, colors. Typing simple documents. Saving documents with proper names.', 'Digital Content Creation II Introduction to word processing. Opening Microsoft Word or similar program. Basic formatting: bold, italic, underline, font size, colors. Typing simple documents. Saving documents with proper names.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 7 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w8-basic-part2', 4, 'Basic Digital Literacy', 2, 8, 'instructional', 'Week 8 · Second Term', NULL, 'Safety and Protection Computer safety basics. Physical safety: handling devices carefully, electrical safety. Data safety: not deleting important files, saving work regularly. Password basics: creating strong passwords, not sharing passwords. Privacy awareness: personal information protection.', 'Safety and Protection Computer safety basics. Physical safety: handling devices carefully, electrical safety. Data safety: not deleting important files, saving work regularly. Password basics: creating strong passwords, not sharing passwords. Privacy awareness: personal information protection.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 8 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w9-basic-part2', 4, 'Basic Digital Literacy', 2, 9, 'instructional', 'Week 9 · Second Term', NULL, 'Safe Internet Use I Introduction to the Internet. What is the Internet: global network. Uses: learning, communication, entertainment, information. Web browser basics: opening browser, typing web addresses. Educational websites for children. Rules for safe browsing.', 'Safe Internet Use I Introduction to the Internet. What is the Internet: global network. Uses: learning, communication, entertainment, information. Web browser basics: opening browser, typing web addresses. Educational websites for children. Rules for safe browsing.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 9 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t2-w10-basic-part2', 4, 'Basic Digital Literacy', 2, 10, 'instructional', 'Week 10 · Second Term', NULL, 'Safe Internet Use II Internet safety rules: never share personal information (name, address, phone, school), never meet online strangers, tell adults about uncomfortable content, use child-friendly websites only. Appropriate online behavior. Screen time limits. Parental supervision importance.', 'Safe Internet Use II Internet safety rules: never share personal information (name, address, phone, school), never meet online strangers, tell adults about uncomfortable content, use child-friendly websites only. Appropriate online behavior. Screen time limits. Parental supervision importance.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 2, Week 10 (Page 827)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
