INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t3-w1-basic-part2', 4, 'Basic Digital Literacy', 3, 1, 'instructional', 'Week 1 · Third Term', NULL, 'Phishing Awareness Understanding phishing: tricking people to get information. Common phishing methods: fake emails, fake websites, suspicious links. Warning signs: spelling errors, urgent messages, asking for passwords. How to avoid phishing: don''t click suspicious links, verify sender, ask adults for help. Reporting suspicious content.', 'Phishing Awareness Understanding phishing: tricking people to get information. Common phishing methods: fake emails, fake websites, suspicious links. Warning signs: spelling errors, urgent messages, asking for passwords. How to avoid phishing: don''t click suspicious links, verify sender, ask adults for help. Reporting suspicious content.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 3, Week 1 (Page 828)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t3-w2-basic-part2', 4, 'Basic Digital Literacy', 3, 2, 'instructional', 'Week 2 · Third Term', NULL, 'Cyberbullying What is cyberbullying: bullying using technology. Forms: mean messages, posting embarrassing content, excluding others online, spreading rumors. Effects: hurt feelings, fear, sadness. How to respond: don''t respond to bullies, save evidence, tell trusted adults, block bullies. Being kind online. Not participating in cyberbullying.', 'Cyberbullying What is cyberbullying: bullying using technology. Forms: mean messages, posting embarrassing content, excluding others online, spreading rumors. Effects: hurt feelings, fear, sadness. How to respond: don''t respond to bullies, save evidence, tell trusted adults, block bullies. Being kind online. Not participating in cyberbullying.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 3, Week 2 (Page 828)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t3-w3-basic-part2', 4, 'Basic Digital Literacy', 3, 3, 'instructional', 'Week 3 · Third Term', NULL, 'Inclusivity in Digital Content Creation Understanding diversity and inclusion online. Respecting everyone online regardless of differences. Creating content that includes everyone. Avoiding stereotypes in digital projects. Using respectful language. Celebrating diversity in digital work. Accessibility basics: content everyone can use.', 'Inclusivity in Digital Content Creation Understanding diversity and inclusion online. Respecting everyone online regardless of differences. Creating content that includes everyone. Avoiding stereotypes in digital projects. Using respectful language. Celebrating diversity in digital work. Accessibility basics: content everyone can use.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 3, Week 3 (Page 828)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p4-t3-w4-basic-part2', 4, 'Basic Digital Literacy', 3, 4, 'instructional', 'Week 4 · Third Term', NULL, 'Basics of Programming Introduction to programming. What is programming: giving instructions to computers. Why learn programming: creates games, apps, websites, solves problems. Programming concepts: commands, sequence (order matters), algorithms (step-by-step solutions). Real- life algorithms: making sandwich, brushing teeth.', 'Basics of Programming Introduction to programming. What is programming: giving instructions to computers. Why learn programming: creates games, apps, websites, solves problems. Programming concepts: commands, sequence (order matters), algorithms (step-by-step solutions). Real- life algorithms: making sandwich, brushing teeth.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 4 Basic Digital Literacy, Term 3, Week 4 (Page 828)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
