INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p5-t1-w1-mathe', 5, 'Mathematics', 1, 1, 'instructional', 'Instructional Week 1 · Numbers up to Millions & Place Value Mastery', 'Universal Basic Education Core Scheme', 'Whole Numbers I (Numbers & Numeration)', 'Place Value up to Millions, Reading, Writing, and Comparing Large Numbers', '[]'::jsonb, '[{"title":"7-Column Place Value Chart","description":"Chart showing Millions (M), Hundred Thousands (HTh), Ten Thousands (TTh), Thousands (Th), Hundreds (H), Tens (T), Units (U).","itemType":"shapes_chart","icon":"📊","caption":"Place Value up to Millions"},{"title":"Federal Budget & Population Analogy","description":"Examples showing population of major Nigerian cities (e.g. Kano state population: over 10 million).","itemType":"nigerian_map","icon":"🏙️","caption":"Real-Life Large Numbers in Nigeria"}]'::jsonb, '[{"id":"p5-mat-q1","question":"How is the number 2,050,400 written in words?","contextNigerian":"Read period by period: Millions, Thousands, Units.","options":["Two million, fifty thousand, four hundred","Two million, five hundred thousand, four hundred","Twenty million, five thousand, four hundred","Two hundred and fifty thousand, four hundred"],"correctAnswerIndex":0,"explanation":"2 is in Millions, 050 is fifty thousand, and 400 is four hundred.","hint":"Look at the thousands period: 050 means fifty."},{"id":"p5-mat-q2","question":"What is the value of the digit 8 in 6,841,200?","contextNigerian":"Multiply 8 by its position (Hundred Thousands).","options":["8,000","80,000","800,000","8,000,000"],"correctAnswerIndex":2,"explanation":"8 is in the Hundred Thousands place, so its value is 800,000.","hint":"8 followed by five zeros."},{"id":"p5-mat-q3","question":"Arrange these figures in ascending order (smallest to largest): 3,100,000; 2,900,000; 3,050,000","contextNigerian":"Ascending means climbing up from the lowest number.","options":["3,100,000; 3,050,000; 2,900,000","2,900,000; 3,050,000; 3,100,000","2,900,000; 3,100,000; 3,050,000","3,050,000; 2,900,000; 3,100,000"],"correctAnswerIndex":1,"explanation":"2.9M is smallest, followed by 3.05M, and 3.1M is largest.","hint":"Start with 2,900,000 because 2 million is less than 3 million."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. The Millions Place Value Chart","teacherSpeech":"Welcome to Primary 5 Mathematics! As future leaders and scholars, you must handle large figures like town populations and government investments. To read a 7-digit number, we group digits into groups of three called periods: Units Period, Thousands Period, and Millions Period!","boardText":"7-DIGIT PLACE VALUE CHART\n\n[Millions] | [Thousands Period] | [Units Period]\n    M      |  HTh   TTh   Th   |   H    T    U\n    3      |   4     8     2   |   5    1    9\n\n• Number: 3,482,519\n• Read as: Three Million, Four Hundred and Eighty-Two Thousand, Five Hundred and Nineteen","bulletPoints":["Group digits in threes starting from the right (Units)","Insert commas between periods for easy reading","Read the number in each period followed by its period name"],"equationOrHighlight":"3,482,519 = 3M + 400Th + 80Th + 2Th + 5H + 1T + 9U","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Expanded Notation & Comparison","teacherSpeech":"To find the value of a digit, multiply the digit by its place value. In 5,320,410, the digit 5 has a value of 5 x 1,000,000 = 5,000,000! When comparing two large numbers, look at the highest place value from the left first.","boardText":"EXPANDED FORM & COMPARISON\n\n• 5,320,410 = 5,000,000 + 300,000 + 20,000 + 400 + 10\n\n• Comparing:\n  4,520,300  vs  4,519,999\n  Both have 4 Millions and 5 Hundred Thousands.\n  Compare Ten Thousands: 20,000 > 10,000!\n  Therefore: 4,520,300 > 4,519,999","bulletPoints":["> means greater than","< means less than","= means equal to"],"equationOrHighlight":"4,520,300 > 4,519,999","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
