INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p6-t1-w1-mathe', 6, 'Mathematics', 1, 1, 'instructional', 'Instructional Week 1 · Numbers up to Billions & Common Entrance Preparation', 'Universal Basic Education Core Scheme', 'Whole Numbers I', 'Place Value up to Millions and Billions, Reading, Writing, Rounding Off, and Roman Numerals', '[]'::jsonb, '[{"title":"National Population and National Revenue Scale","description":"Examples showing Nigeria population (over 200 million) and federal budgets in Trillions and Billions of Naira.","itemType":"nigerian_map","icon":"🇳🇬","caption":"National Figures in Billions"},{"title":"Roman Numerals Anchor Chart","description":"Chart listing I (1), V (5), X (10), L (50), C (100), D (500), M (1000).","itemType":"shapes_chart","icon":"🏛️","caption":"Roman Numerals up to 1,000 (M)"}]'::jsonb, '[{"id":"p6-mat-q1","question":"Round off 78,542 to the nearest thousand.","contextNigerian":"Look at the hundreds digit (5). Does 5 cause a round up or down?","options":["78,000","79,000","78,500","80,000"],"correctAnswerIndex":1,"explanation":"The hundreds digit is 5, so we round up 78,000 to 79,000.","hint":"Whenever the deciding digit is 5 or more, round up."},{"id":"p6-mat-q2","question":"What is the Roman numeral for 450?","contextNigerian":"400 is CD (500 - 100) and 50 is L.","options":["CCCCL","CDL","DCL","XDL"],"correctAnswerIndex":1,"explanation":"CD is 400 and L is 50, so 450 is CDL.","hint":"Use subtraction principle for 400: C before D."},{"id":"p6-mat-q3","question":"A state government allocated ₦3,540,800,000 for building primary schools. What period is the digit 3 in?","contextNigerian":"Count the digits from right to left: units, thousands, millions, billions.","options":["Thousands period","Millions period","Billions period","Trillions period"],"correctAnswerIndex":2,"explanation":"The digit 3 is in the Billions period (3 Billion Naira).","hint":"It is the 10th digit from the right."}]'::jsonb, '[]'::jsonb, '[{"stepNumber":1,"title":"1. Numbers up to Billions (10 Digits)","teacherSpeech":"Bawo ni, scholars! Welcome to Primary 6. Today we step into Billions. One Billion is 1 followed by nine zeros: 1,000,000,000. It is equal to one thousand millions! Let us see how the periods work together.","boardText":"THE 4 PERIODS OF LARGE NUMBERS\n\n[Billions] | [Millions] | [Thousands] | [Units]\n    B      |   H  T  U  |   H  T  U   |  H  T  U\n    4      |   2  5  0  |   1  8  0   |  6  0  0\n\n• Read as: Four Billion, Two Hundred and Fifty Million, One Hundred and Eighty Thousand, Six Hundred.","bulletPoints":["1 Billion = 1,000,000,000 (10 digits)","Commas separate each 3-digit period","Read each group of three digits just like in Primary 3, then add the period name"],"equationOrHighlight":"1 Billion = 1,000 Million = 1,000,000,000","diagramSvgType":"shapes"},{"stepNumber":2,"title":"2. Rounding Off Numbers & Roman Numerals","teacherSpeech":"To round off to the nearest 1,000, look at the Hundreds digit. If it is 5 or more, round UP by adding 1 to the thousands digit. If less than 5, round DOWN. For Roman numerals, remember: I=1, V=5, X=10, L=50, C=100, D=500, M=1000!","boardText":"ROUNDING OFF RULES & ROMAN NUMERALS\n\n• Rounding 4,862 to nearest 100:\n  Tens digit is 6 (>=5) -> Round UP to 4,900!\n\n• Rounding 5,420 to nearest 1,000:\n  Hundreds digit is 4 (<5) -> Round DOWN to 5,000!\n\n• Roman Numerals Key:\n  I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000\n  XC = 100 - 10 = 90\n  CD = 500 - 100 = 400","bulletPoints":["5 or more -> Round UP","4 or less -> Round DOWN","Subtract when a smaller Roman numeral precedes a larger one (IV = 4, IX = 9)"],"equationOrHighlight":"C = 100 | D = 500 | M = 1,000","diagramSvgType":"shapes"}]'::jsonb, 'PUBLISHED', 'nerdc-based-v1', 'NERDC National Curriculum for Basic Education', 'Universal Basic Education (UBE) Primary Curriculum Standards') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
