INSERT INTO curriculum_records (id, grade, subject, term, week, week_type, period_title, theme, topic, subtopic, learning_objectives, concrete_visual_aids, assessment_questions, practice_questions, whiteboard_steps, publishing_status, curriculum_version, source_document, source_reference) VALUES ('p6-t3-w9-frenc', 6, 'French Language', 3, 9, 'closing', 'Week 9 · Third Term', NULL, 'Communication Extended conversations; Telephone conversations - Allô, Avancée et Expression Orale C''est... à l''appareil, Puis-je parler à...?; Letter writing basics - Cher/Chère..., opening and closing; Email format; Invitations; Expressing opinions - Je pense que..., À mon avis...; Agreeing and disagreeing - Je suis d''accord, Je ne suis pas d''accord', 'Communication Extended conversations; Telephone conversations - Allô, Avancée et Expression Orale C''est... à l''appareil, Puis-je parler à...?; Letter writing basics - Cher/Chère..., opening and closing; Email format; Invitations; Expressing opinions - Je pense que..., À mon avis...; Agreeing and disagreeing - Je suis d''accord, Je ne suis pas d''accord', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'DRAFT', 'complete-primary-scheme-v1', 'THE COMPLETE SCHEME OF WORK FOR PRE-PRIMARY & PRIMARY SCHOOLS.pdf', 'Pawills Consulting, Primary 6 French Language, Term 3, Week 9 (Page 954)') ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, subtopic = EXCLUDED.subtopic, publishing_status = EXCLUDED.publishing_status, updated_at = CURRENT_TIMESTAMP;
